template <typename Derived>
struct PolicyBase {
    // Static Dispatch: Compile-time polymorphism (CRTP)
    void execute() const {
        // Compiler generates specialized 'execute' for each Derived
        static_cast<const Derived*>(this)->implementation();
    }
};

struct OptimizedPolicyA : PolicyBase<OptimizedPolicyA> {
    void implementation() const {
        // Specialized code path A
    }
};

struct OptimizedPolicyB : PolicyBase<OptimizedPolicyB> {
    void implementation() const {
        // Specialized code path B (Aggressive Inlining Possible)
    }
};

// Runtime Overhead: Zero (No vtable lookup, compiler knows exact type)
// Cost: Increased Compilation Time, Code Bloat (if many Derived types)
